<script setup lang="ts">
import { computed, ref, useId, watch } from 'vue'
import { ArrowRight, Check, Minus, Plus, Star } from 'lucide-vue-next'
export interface ShopVariant { name: string; color: string; image: string; available?: boolean }
const props = withDefaults(defineProps<{ name?: string; store?: string; price?: number; currency?: string; rating?: number; reviewCount?: number; inStock?: boolean; maxQuantity?: number; initialVariant?: string; variants?: ShopVariant[]; gallery?: string[] }>(), {
  name: 'Baby Changing Mat', store: 'Gathre', price: 160, currency: 'HKD', rating: 4.9, reviewCount: 160, inStock: true, maxQuantity: 10, initialVariant: 'Camel',
  variants: () => [{ name: 'Camel', color: '#b9865b', image: '/assets/shop/mat-camel.jpg' }, { name: 'Ivory', color: '#e8e4d6', image: '/assets/shop/mat-ivory.jpg' }],
  gallery: () => ['/assets/shop/changing-mat.jpg'],
})
const emit = defineEmits<{ 'update:variant': [name: string]; add: [item: { name: string; variant: string; quantity: number; price: number }] }>()
const id = useId()
const selectedName = ref(props.initialVariant)
const selectedImage = ref('')
const quantity = ref(1)
const added = ref(false)
const selected = computed(() => props.variants.find(item => item.name === selectedName.value) ?? props.variants[0])
const images = computed(() => [...new Set([selected.value?.image, ...props.gallery].filter((value): value is string => Boolean(value)))])
const activeImage = computed(() => images.value.includes(selectedImage.value) ? selectedImage.value : images.value[0])
const quantityLimit = computed(() => Math.max(1, Math.floor(props.maxQuantity) || 1))
const available = computed(() => props.inStock && selected.value?.available !== false)
const money = computed(() => { try { return new Intl.NumberFormat('en-HK', { style: 'currency', currency: props.currency }).format(props.price) } catch { return `${props.price.toFixed(2)} ${props.currency}` } })
watch(() => props.initialVariant, value => { selectedName.value = value; selectedImage.value = ''; added.value = false })
watch(quantityLimit, limit => { quantity.value = Math.min(quantity.value, limit) })
function selectVariant(value: string) { selectedName.value = value; selectedImage.value = ''; added.value = false; emit('update:variant', value) }
function changeQuantity(delta: number) { quantity.value = Math.max(1, Math.min(quantityLimit.value, quantity.value + delta)); added.value = false }
function add() { if (!available.value) return; added.value = true; emit('add', { name: props.name, variant: selected.value?.name ?? '', quantity: quantity.value, price: props.price }) }
</script>
<template>
  <section class="product-configurator" :aria-label="name">
    <div class="configurator-layout"><div class="product-gallery"><div class="hero-image"><img v-if="activeImage" :src="activeImage" :alt="`${name}, ${selected?.name || ''}`" /><span v-else>{{ name }}</span></div><div v-if="images.length > 1" class="thumbnails"><button v-for="(image,index) in images" :key="image" type="button" :aria-label="`View product image ${index+1}`" :aria-pressed="activeImage === image" @click="selectedImage = image"><img :src="image" alt="" /></button></div></div>
      <div class="product-details"><small class="store">{{ store }}</small><h3>{{ name }}</h3><div v-if="reviewCount > 0" class="rating"><Star :size="12" fill="currentColor" aria-hidden="true" /><span>{{ Math.max(0, Math.min(5, rating)).toFixed(1) }}</span><small>{{ reviewCount }} ratings</small></div><strong class="price">{{ money }}</strong>
        <fieldset v-if="variants.length"><legend>Color <strong>{{ selected?.name }}</strong></legend><div class="variants"><label v-for="variant in variants" :key="variant.name" :title="variant.available === false ? `${variant.name} - unavailable` : variant.name"><input :checked="selected?.name === variant.name" type="radio" :name="id" :value="variant.name" :disabled="variant.available === false" :aria-label="variant.name" @change="selectVariant(variant.name)" /><span :style="{ background: variant.color }"><Check v-if="selected?.name === variant.name" :size="14" aria-hidden="true" /></span></label></div></fieldset>
        <div class="quantity-row"><span>Quantity</span><div><button type="button" aria-label="Decrease quantity" :disabled="quantity <= 1" @click="changeQuantity(-1)"><Minus :size="13" aria-hidden="true" /></button><output aria-label="Quantity">{{ quantity }}</output><button type="button" aria-label="Increase quantity" :disabled="quantity >= quantityLimit" @click="changeQuantity(1)"><Plus :size="13" aria-hidden="true" /></button></div></div>
        <button class="add-button" type="button" :disabled="!available" @click="add"><Check v-if="added" :size="16" aria-hidden="true" /><span>{{ !available ? 'Out of stock' : added ? `${quantity} added to cart` : 'Add to cart' }}</span><ArrowRight v-if="!added && available" :size="16" aria-hidden="true" /></button>
      </div>
    </div>
  </section>
</template>
<style scoped>
@font-face{font-family:'Library Shop';src:url('/assets/shop/GTStandard-MRegular.woff2') format('woff2');font-weight:400;font-display:swap}@font-face{font-family:'Library Shop';src:url('/assets/shop/GTStandard-MSemibold.woff2') format('woff2');font-weight:600 800;font-display:swap}.product-configurator,.product-configurator *{box-sizing:border-box}.product-configurator{width:100%;max-width:600px;color:#080808;font-family:'Library Shop',Arial,sans-serif;letter-spacing:0;container-type:inline-size}.configurator-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:25px;align-items:center}.hero-image{display:grid;place-items:center;aspect-ratio:1;width:100%;overflow:hidden;border-radius:16px;background:#f3f3f3}.hero-image img{display:block;width:100%;height:100%;object-fit:cover}.hero-image>span{padding:20px;font-size:18px;overflow-wrap:anywhere}.thumbnails{display:flex;gap:7px;margin-top:9px}.thumbnails button{width:42px;height:42px;padding:2px;border:1px solid #dedede;border-radius:7px;background:transparent;cursor:pointer}.thumbnails button[aria-pressed=true]{border:2px solid #080808;padding:1px}.thumbnails img{display:block;width:100%;height:100%;object-fit:cover;border-radius:4px}.product-details{min-width:0}.store{font-size:11px;color:#686868}.product-details h3{margin:7px 0;font-size:23px;line-height:1.1;overflow-wrap:anywhere}.rating{display:flex;align-items:center;gap:5px;font-size:11px}.rating svg{color:#a38b14}.rating small{font-size:10px;color:#777}.price{display:block;margin-top:15px;font-size:22px}.product-details fieldset{margin:17px 0;padding:0;border:0}.product-details legend{margin-bottom:10px;font-size:11px}.product-details legend strong{margin-left:7px}.variants{display:flex;flex-wrap:wrap;gap:11px}.variants label{position:relative;cursor:pointer}.variants input{position:absolute;opacity:0}.variants label>span{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;border:1px solid #bbb}.variants input:checked+span{outline:2px solid #080808;outline-offset:3px}.variants input:disabled+span{opacity:.3;cursor:not-allowed}.variants svg{color:#fff;background:#555;border-radius:50%;padding:1px}.variants input:focus-visible+span{outline:2px solid #5433eb;outline-offset:3px}.quantity-row{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px}.quantity-row>div{display:grid;grid-template-columns:repeat(3,30px);height:31px;align-items:center;border:1px solid #ddd;border-radius:999px}.quantity-row button{display:grid;place-items:center;height:28px;padding:0;border:0;background:transparent;color:inherit;cursor:pointer}.quantity-row output{text-align:center}.quantity-row button:disabled{opacity:.3;cursor:not-allowed}.add-button{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:43px;margin-top:17px;padding:10px;border:0;border-radius:999px;background:#5433eb;color:#fff;font:inherit;font-size:12px;cursor:pointer}.add-button:disabled{background:#ddd;color:#777;cursor:not-allowed}.product-configurator button:focus-visible{outline:2px solid #5433eb;outline-offset:2px}@container(max-width:410px){.configurator-layout{grid-template-columns:1fr;gap:18px}.hero-image{aspect-ratio:1.35}.thumbnails{margin-top:8px}.product-details h3{font-size:22px}.product-details fieldset{margin:15px 0}.price{margin-top:12px}}
</style>
